import{_ as a,a as r,c as i,ac as t}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"英语：错因记录与能力回看","description":"从明确前置到具体题目、参考解答及适用边界。英语：错因记录与能力回看","frontmatter":{"title":"英语：错因记录与能力回看","description":"从明确前置到具体题目、参考解答及适用边界。英语：错因记录与能力回看","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"错因与能力回看","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"英语：从能力自测到表达","summary":"从明确前置到具体题目、参考解答及适用边界。英语：错因记录与能力回看","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"英语：借阅沟通完整练习","link":"/life/english/practice/workshop"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"英语：借阅沟通完整练习","link":"/life/english/practice/workshop"},"next":false},"headers":[],"relativePath":"life/english/review/reflection.md","filePath":"life/english/review/reflection.md"}'),l={name:"life/english/review/reflection.md"};function n(o,e,s,c,d,p){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="英语-错因记录与能力回看" tabindex="-1">英语：错因记录与能力回看 <a class="header-anchor" href="#英语-错因记录与能力回看" aria-label="Permalink to &quot;英语：错因记录与能力回看&quot;">​</a></h1><p>本课按实际能力与证据阅读；以下例子为原创教学材料，不代表用户事实。</p><h2 id="error-log" tabindex="-1">错因分类 <a class="header-anchor" href="#error-log" aria-label="Permalink to &quot;错因分类 {#error-log}&quot;">​</a></h2><p>英语 错因分类把错误定位到证据提取、词义方向、句法形式或表达缺口。“Mei lend a book from Li yesterday.”至少有两处：借入应选 borrow，过去时应为 borrowed。只记“粗心”无法知道下一次练什么。</p><p>错题卡写：原题、我的答案、正确答案、一个可解释差异的规则、新例句。新例句为 “Li lent a book to Mei yesterday.”，它验证借出视角。若新句仍错，退回借入借出对照；若只在时间标记错，单练过去时。不要同时抄十遍正确句而没有遮答提取。</p><h2 id="retrieval" tabindex="-1">延迟提取 <a class="header-anchor" href="#retrieval" aria-label="Permalink to &quot;延迟提取 {#retrieval}&quot;">​</a></h2><p>英语 延迟提取通过遮住答案再作答检查是否能独立使用。练习安排示例：当天做借阅题；隔一天换人物和书名；隔一周给新短文，在不看笔记时回答并写两句请求。这是一个可调整方案，不是普适学习时长。</p><p>判定分别记内容正确、语法可懂、是否用提示。三项都记比只算总分更能找弱点。比如内容三问全对但请求缺时间，下一轮练具体提问；借助答案才写出，不计独立完成。因缺音频，本套纸面练习的成绩不作为听说测评分数。</p><h2 id="next" tabindex="-1">下一阶段 <a class="header-anchor" href="#next" aria-label="Permalink to &quot;下一阶段 {#next}&quot;">​</a></h2><p>英语 下一阶段依据任务迁移而不是章节读完。用新场景“周六取回修好的自行车”，写询问时间、确认地点、说明过去问题三句。参考：“What time can I collect my bike on Saturday?” “Is the pickup point still on Green Street?” “The brake made a noise yesterday.”</p><p>若仍写不出一般疑问句，回句子骨架；若 yesterday 后形式错，回时间与体；若语法对却漏地点，回口语澄清。旧<a href="/life/english/reference/education">分阶段草案</a>只作历史清单，未对应官方学段；旧<a href="/life/english/foundations/5-sentence_structure">句型草稿</a>的分类不当作标准答案。</p>',11)])])}const f=a(l,[["render",n]]);export{g as __pageData,f as default};
